control.code:
def control(sdk, offset, displacement, rotation, ticks):
    state = sdk.get_state()
    for tick in range(min(ticks, budget(state))):
        if opened(state):
            break
        handle = state["objects"]["handle"]["pos"]
        eef = state["eef_pos"]
        action = [
            clip(
                20.0 * (handle[i] + offset[i] + displacement[i] - eef[i]),
                -1.0,
                1.0,
            )
            for i in range(3)
        ]
        action.extend(rotation)
        action.append(1.0)
        sdk.step_raw(action, steps=1)
        state = sdk.get_state()
    return state

actuate_gripper.code:
def actuate_gripper(sdk, action, ticks=15):
    budget = min(ticks, remaining_steps(sdk))
    if budget > 0:
        sdk.set_gripper(action, steps=budget)

cube_is_lifted.code:
def cube_is_lifted(state, initial_height, minimum_rise=0.10):
    cube = state["objects"]["cube"]["pos"]
    hand = state["eef_pos"]
    separation = sqrt(sum((cube[i] - hand[i]) ** 2 for i in range(3)))
    return (
        cube[2] >= initial_height + minimum_rise
        and horizontal_distance(cube, hand) < 0.045
        and separation < 0.09
    )

nearest_cube_yaw.code:
def nearest_cube_yaw(cube_yaw, current_yaw):
    period = pi / 2.0
    return cube_yaw + round((current_yaw - cube_yaw) / period) * period

remaining_steps.code:
def remaining_steps(sdk):
    state = sdk.get_state()
    return max(0, state["max_steps"] - state["steps_used"])

center_move.code:
def center_move(sdk, target, ticks, tolerance=0.006, reserve=0):
    state = sdk.get_state()
    hand = state["eef_pos"]
    nut = state["objects"]["nut"]["pos"]
    return move(
        sdk,
        [hand[i] + target[i] - nut[i] for i in range(3)],
        state["eef_yaw"], "close", ticks, tolerance, reserve
    )

grip.code:
def grip(sdk, action, ticks, reserve=0):
    budget = min(ticks, remaining(sdk) - reserve)
    if budget > 0:
        sdk.set_gripper(action, steps=budget)

move.code:
def move(sdk, position, yaw, gripper, ticks, tolerance=0.006, reserve=0):
    budget = min(ticks, remaining(sdk) - reserve)
    if budget <= 0:
        return False
    result = sdk.move_to(
        position, yaw=yaw, gripper=gripper,
        max_steps=budget, tol=tolerance
    )
    return result["reached"]

remaining.code:
def remaining(sdk):
    state = sdk.get_state()
    return max(0, min(400, state["max_steps"]) - state["steps_used"])

policy_gripper.code:
def policy_gripper(sdk, action, steps):
    budget = min(steps, policy_remaining(sdk))
    if budget > 0:
        sdk.set_gripper(action, steps=budget)

policy_holding.code:
def policy_holding(state, offset):
    return (
        0.012 < state["gripper_width"] < 0.075
        and policy_distance(
            state["eef_pos"],
            policy_target(state["objects"]["can"]["pos"], offset)
        ) < 0.04
    )

policy_move.code:
def policy_move(sdk, target, yaw, grip, steps, tolerance=0.012):
    budget = min(steps, policy_remaining(sdk))
    if budget <= 0:
        return False
    sdk.move_to(
        target, yaw=yaw, gripper=grip,
        max_steps=budget, tol=tolerance
    )
    return policy_distance(sdk.get_state()["eef_pos"], target) <= tolerance

policy_remaining.code:
def policy_remaining(sdk):
    state = sdk.get_state()
    return max(0, min(400, state["max_steps"]) - state["steps_used"])
